-- ═══════════════════════════════════════════════════════════════════
-- NOVAMARKET TECH — Sincronización Dataset Canónico → SQLite
-- Fuente: S01_Ventas_Novamarket_Datos_Limpios.csv
-- Resultado verificado: Leticia = −$79,342 / −50.4%
-- Compatible: SQLite 3.x (Antigravity / VS Code)
-- Aplica a: Novamarket_S07.db  y  Novamarket_S08S09.db
-- ═══════════════════════════════════════════════════════════════════

-- ╔══════════════════════════════════════════════════════════════════╗
-- ║  INSTRUCCIONES DE USO                                           ║
-- ║  1. Abrir el archivo .db en VS Code (SQLite Viewer o extensión) ║
-- ║  2. Abrir una terminal en la carpeta del proyecto               ║
-- ║  3. Ejecutar:                                                   ║
-- ║     sqlite3 Novamarket_S07.db < S06_INSERT_FactVentas_v2.sql   ║
-- ║  4. Repetir para Novamarket_S08S09.db                          ║
-- ║  5. Verificar: las 3 SELECTs al final deben dar −$79,342       ║
-- ╚══════════════════════════════════════════════════════════════════╝

PRAGMA foreign_keys = OFF;

-- ── PASO 1: Actualizar DimProducto con precios y costos reales ─────
-- Los valores del S06 original eran incorrectos vs el CSV canónico.
-- Smartphone: Precio 1200→800, Costo 800→550
-- Audifonos:  Precio  150→450, Costo  90→250
DELETE FROM DimProducto;

-- ── PASO 2: Actualizar DimCiudad ───────────────────────────────────
-- Factor_Envio actualizado: Leticia=11.0 refleja $1,650 real (vs $150 Bogotá)
-- Costo_Envio real: Bogotá=150, Medellín=180, Cali=200,
--                   Barranquilla=220, Cartagena=250, Leticia=1650
DELETE FROM DimCiudad;

-- ── PASO 3: Recargar DimFecha (Sep–Nov 2023) ───────────────────────
DELETE FROM DimFecha;

-- ── PASO 4: Reemplazar FactVentas con 500 registros canónicos ───────
-- Leticia: 70 transacciones con Costo_Envio=$1,650
-- Resultado esperado: Utilidad Leticia = −$79,342 / Margen = −50.4%
DELETE FROM FactVentas;

PRAGMA foreign_keys = ON;

-- ── PASO 5: Verificaciones ─────────────────────────────────────────
-- Ejecutar estas 3 SELECTs. Si los números coinciden, la sincronización
-- fue exitosa y el curso queda 100% consistente.

-- CHECK 1: Leticia debe dar −79341.50 / −50.4%
SELECT
    'CHECK_LETICIA'          AS Verificacion,
    COUNT(*)                 AS Transacciones,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio), 2) AS Utilidad_Neta,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio)
          / SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)) * 100, 1) AS Margen_Pct
FROM FactVentas f
    JOIN DimProducto dp ON f.ProductoID = dp.ProductoID
    JOIN DimCiudad   dc ON f.CiudadID   = dc.CiudadID
WHERE dc.Ciudad = 'Leticia';
-- ESPERADO: Transacciones=70 | Utilidad_Neta=-79341.50 | Margen_Pct=-50.4

-- CHECK 2: Empresa total debe dar 121930.50 / 10.4%
SELECT
    'CHECK_TOTAL'            AS Verificacion,
    COUNT(*)                 AS Transacciones,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio), 2) AS Utilidad_Total,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio)
          / SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)) * 100, 1) AS Margen_Global
FROM FactVentas f
    JOIN DimProducto dp ON f.ProductoID = dp.ProductoID;
-- ESPERADO: Transacciones=500 | Utilidad_Total=121930.50 | Margen_Global=10.4

-- CHECK 3: Ranking por ciudad (Leticia debe aparecer primera, más negativa)
SELECT
    dc.Ciudad                AS Ciudad,
    COUNT(*)                 AS Transacciones,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio), 0) AS Utilidad_Neta,
    ROUND(SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)
        - dp.Costo_Unitario * f.Cantidad
        - f.Costo_Envio)
          / SUM(f.Precio_Venta * f.Cantidad * (1 - f.Descuento_Pct)) * 100, 1) AS Margen_Pct
FROM FactVentas f
    JOIN DimProducto dp ON f.ProductoID = dp.ProductoID
    JOIN DimCiudad   dc ON f.CiudadID   = dc.CiudadID
GROUP BY dc.CiudadID, dc.Ciudad
ORDER BY Utilidad_Neta ASC;
-- ESPERADO: Leticia primera con -79342 | Bogotá última con mayor utilidad
